// A todo has: id, title, done, createdAt. No due date, no tags, no owner.
// Saving and importing decisions live in backup.js (persist, importBackup); this file only wires them to the page.
let todos = store.load().todos;
let filter = 'all';
// The one Undo of the app (plan han-chot-cho-viec, Q7): { restore, timer } while the "Hoàn tác" button shows, else null.
// Kept in page memory only, never saved.
let undo = null;
const UNDO_MS = 10000;

const $ = (sel) => document.querySelector(sel);

function add(title) {
  todos.push({ id: crypto.randomUUID(), title: title.trim(), done: false, createdAt: Date.now() });
  commit();
}

function toggle(id) {
  const t = todos.find((x) => x.id === id);
  if (t) t.done = !t.done;
  commit();
}

function remove(id) {
  todos = todos.filter((x) => x.id !== id);
  commit();
}

function commit() {
  save();
  render();
}

// Saves and says so only when saving failed (U1). Split from render() so a change can be saved before the list is redrawn.
function save() {
  show(persist(store, todos).message);
}

// Every new message hides the Undo button: add, toggle, remove, import (and export) all call show(). Filtering does not.
function show(message) {
  clearUndo();
  $('#message').textContent = message || '';
}

// Shared by every Undo (due dates now, renaming in PR 2). restore() puts the old value back in todos; this saves it.
// message is set with textContent like every other message, so a title inside it is never read as HTML (S3).
function offerUndo(message, restore) {
  show(message);
  $('#undo').hidden = false;
  undo = { restore, timer: setTimeout(clearUndo, UNDO_MS) };
}

function clearUndo() {
  if (undo) clearTimeout(undo.timer);
  undo = null;
  $('#undo').hidden = true;
}

function undoLast() {
  if (!undo) return;
  const { restore } = undo;
  clearUndo();
  restore();
  const { message } = persist(store, todos);
  render();
  show(message || DUE_TEXT.undone); // D7 when saving failed, else D9 (plan Q5)
}

function visible() {
  if (filter === 'open') return todos.filter((t) => !t.done);
  if (filter === 'done') return todos.filter((t) => t.done);
  return todos;
}

function render() {
  const list = $('#list');
  list.innerHTML = '';
  for (const t of visible()) {
    const li = document.createElement('li');
    li.className = t.done ? 'done' : '';
    li.innerHTML = `<label><input type="checkbox" ${t.done ? 'checked' : ''}> <span></span></label><button aria-label="Xoá">×</button>`;
    li.querySelector('span').textContent = t.title;
    li.querySelector('input').onchange = () => toggle(t.id);
    li.querySelector('button').onclick = () => remove(t.id);
    list.append(li);
  }
  const open = todos.filter((t) => !t.done).length;
  // Every todo done (and the list not empty): say so instead of "0 việc chưa xong" (Thảo, PR 3).
  $('#count').textContent = open === 0 && todos.length > 0 ? 'Đã xong hết' : `${formatCount(open)} việc chưa xong`;
  $('#unreadable').hidden = !store.readError;
  // Based on the whole list, not the filter; and not shown on a read error, where the list only looks empty.
  $('#empty').hidden = todos.length > 0 || store.readError;
}

// Resolves true only when the customer picks "Thay"; Esc and "Huỷ" resolve false.
function ask(question) {
  const dialog = $('#confirm');
  $('#confirm-text').textContent = question;
  dialog.returnValue = '';
  dialog.showModal();
  return new Promise((resolve) => {
    dialog.addEventListener('close', () => resolve(dialog.returnValue === 'yes'), { once: true });
  });
}

$('#add').onsubmit = (e) => {
  e.preventDefault();
  const input = $('#title');
  if (input.value.trim()) add(input.value);
  input.value = '';
};

$('#filters').onclick = (e) => {
  const f = e.target.dataset.filter;
  if (!f) return;
  filter = f;
  document.querySelectorAll('#filters button').forEach((b) => b.classList.toggle('on', b.dataset.filter === f));
  render();
};

$('#undo').onclick = undoLast;

$('#export').onclick = () => {
  if (todos.length === 0) return show(MESSAGES.nothingToBackUp);
  const text = toBackupText(todos);
  const url = URL.createObjectURL(new Blob([text], { type: 'application/json' }));
  const a = document.createElement('a');
  a.href = url;
  a.download = backupFileName(new Date());
  document.body.append(a);
  a.click();
  a.remove();
  // Revoking right after click() can break the download on Safari iOS, so wait.
  setTimeout(() => URL.revokeObjectURL(url), 10000);
  show(tooBigToImport(text) ? MESSAGES.backupTooBig : fill(MESSAGES.backedUp, { n: todos.length }));
};

$('#import').onchange = async (e) => {
  const input = e.target;
  const file = input.files[0];
  input.value = ''; // so the same file can be picked again
  if (!file) return;
  show(MESSAGES.reading);
  // Counted when importBackup decides whether to ask (after the file is read), not now: another import, an add or a
  // delete may change the list while the file is being read. importBackup only reads current.length and returns
  // current itself when nothing was replaced.
  const current = { get length() { return todos.length; } };
  const result = await importBackup({ store, current, file, ask });
  if (result.todos !== current) todos = result.todos;
  show(result.message);
  render();
};

$('#unreadable').textContent = MESSAGES.unreadable;
$('#empty').textContent = MESSAGES.emptyList;
render();
<!doctype html>
<html lang="vi">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Todo</title>
  <link rel="stylesheet" href="style.css">
</head>
<body>
  <main>
    <h1>Todo</h1>
    <div id="notices" role="status" aria-live="polite">
      <p id="unreadable" class="banner" hidden></p>
      <p id="message"></p>
      <button type="button" id="undo" hidden>Hoàn tác</button>
    </div>
    <form id="add">
      <input id="title" placeholder="Việc cần làm…" autocomplete="off" required>
      <button>Thêm</button>
    </form>
    <nav id="filters">
      <button data-filter="all" class="on">Tất cả</button>
      <button data-filter="open">Chưa xong</button>
      <button data-filter="done">Đã xong</button>
    </nav>
    <ul id="list"></ul>
    <p id="empty" hidden></p>
    <p id="count"></p>
    <div id="backup">
      <button type="button" id="export">Sao lưu ra file</button>
      <label id="import-label">Nhập từ file<input type="file" id="import"></label>
    </div>
    <p id="where-kept" class="note">Danh sách chỉ được lưu trên trình duyệt này, nên xoá dữ liệu trang web, đổi trình duyệt hoặc đổi máy là mất, trừ khi bạn đã sao lưu ra file.</p>
  </main>
  <dialog id="confirm" aria-labelledby="confirm-text">
    <form method="dialog">
      <p id="confirm-text"></p>
      <button value="yes">Thay</button>
      <button value="no" autofocus>Huỷ</button>
    </form>
  </dialog>
  <script src="store.js"></script>
  <script src="due.js"></script>
  <script src="backup.js"></script>
  <script src="app.js"></script>
</body>
</html>
body { font: 16px/1.5 system-ui, sans-serif; background: #f6f6f4; color: #222; margin: 0; }
main { max-width: 32rem; margin: 3rem auto; padding: 0 1rem; }
form { display: flex; gap: .5rem; }
input#title { flex: 1; padding: .5rem; }
nav { margin: 1rem 0; display: flex; gap: .25rem; }
nav button.on { font-weight: 700; }
ul { list-style: none; padding: 0; }
li { display: flex; justify-content: space-between; padding: .4rem 0; border-bottom: 1px solid #ddd; }
li.done span { text-decoration: line-through; color: #888; }
.banner { background: #fff4e5; border: 1px solid #d08a2a; border-radius: 4px; padding: .6rem .8rem; }
#message { background: #eaf1fb; border-radius: 4px; padding: .5rem .8rem; }
#message:empty { display: none; }
#undo { margin-top: .25rem; }
#undo:focus { outline: 2px solid #1a5fd0; outline-offset: 2px; }
#empty, .note { color: #555; }
.note { font-size: .875rem; }
#backup { display: flex; gap: .5rem; align-items: center; margin: 1rem 0 .25rem; }
#import-label { position: relative; border: 1px solid #767676; border-radius: 3px; background: #efefef; padding: 1px 6px; cursor: pointer; }
#import-label:focus-within { outline: 2px solid #1a5fd0; outline-offset: 2px; }
/* The file input stays focusable and clickable through its label; only its own button is hidden. */
#import { position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0; cursor: pointer; }
dialog { border: 1px solid #bbb; border-radius: 6px; max-width: 24rem; }
dialog form { flex-wrap: wrap; justify-content: flex-end; }
dialog p { flex-basis: 100%; margin-top: 0; }
/* On :focus, not :focus-visible: after the file picker closes, Firefox does not treat the autofocused "Huỷ" as keyboard focus. */
dialog button:focus { outline: 2px solid #1a5fd0; outline-offset: 2px; }
// Due dates (plan/2026-10-19-han-chot-cho-viec.md, Q2). No DOM and no browser storage here, so this file can be tested in Node.
// A due date is a string YYYY-MM-DD on the todo (key `dueDate`, absent when there is none). "Today" is the machine's own day
// (local time), never the UTC day: no toISOString and no Date built from a due date string except through Date.UTC below.

// Every new sentence and label of the due date feature (plan, Câu chữ). {title} is filled by the caller, {date} by formatDueDate.
const DUE_TEXT = {
  addLabel: 'Hạn chót', // D1
  rowLabel: 'Hạn chót của việc {title}', // D2
  dueOn: 'Hạn {date}', // D3
  overdue: 'Quá hạn', // D4
  cleared: 'Đã bỏ hạn chót của việc {title}.', // D5
  undo: 'Hoàn tác', // D6
  sortLabel: 'Xếp theo', // D8
  sortAdded: 'Thứ tự thêm', // D8
  sortDue: 'Hạn chót', // D8
  undone: 'Đã hoàn tác.', // D9
};

// A string in the fixed form YYYY-MM-DD that is a real day (no 2026-02-30). Date.UTC + getUTC* so the time zone plays no part.
function isValidDueDate(v) {
  if (typeof v !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(v)) return false;
  const [y, m, d] = v.split('-').map(Number);
  const date = new Date(Date.UTC(y, m - 1, d));
  return date.getUTCFullYear() === y && date.getUTCMonth() === m - 1 && date.getUTCDate() === d;
}

// The machine's own day as YYYY-MM-DD (A9).
function localDateString(date) {
  const pad = (n) => String(n).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

// today is localDateString(new Date()). Comparing strings works because the form is fixed (4-2-2 digits).
// Due today is not overdue (A6); a done todo never is (A7); a broken value counts as no due date (A14).
function isOverdue(todo, today) {
  return !todo.done && isValidDueDate(todo.dueDate) && todo.dueDate < today;
}

// "Hạn DD/MM/YYYY" (A5). Only call it with a valid due date.
function formatDueDate(s) {
  const [y, m, d] = s.split('-');
  return DUE_TEXT.dueOn.replace('{date}', `${d}/${m}/${y}`);
}

// A new array (the saved list keeps its added order, Q6): valid dates earliest first, then todos with no due date or a broken
// one. Ties keep the original order, by index, without relying on sort stability (A12).
function sortByDue(todos) {
  const key = (t) => (isValidDueDate(t.dueDate) ? t.dueDate : null);
  return todos
    .map((t, i) => ({ t, i, k: key(t) }))
    .sort((a, b) => {
      if (a.k !== b.k) {
        if (a.k === null) return 1;
        if (b.k === null) return -1;
        return a.k < b.k ? -1 : 1;
      }
      return a.i - b.i;
    })
    .map((x) => x.t);
}

if (typeof module !== 'undefined') {
  module.exports = { DUE_TEXT, isValidDueDate, localDateString, isOverdue, formatDueDate, sortByDue };
}

