// Pins what add() in app/app.js makes, so a backup the app itself made always imports again (Khoa's review of commit B:
// isValidTodo rejects whitespace-only titles and non-string ids). app.js is a plain page script with no exports, so it
// runs unchanged in a vm context with a minimal fake page. Run: node --test
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const crypto = require('node:crypto');
const backup = require('../app/backup.js');
const due = require('../app/due.js');

const appJs = fs.readFileSync(path.join(__dirname, '..', 'app', 'app.js'), 'utf8');

function fakeElement() {
  const el = {
    textContent: '', innerHTML: '', hidden: false, value: '', className: '', dataset: {},
    append() {},
    querySelector(sel) { return (el.children[sel] ||= fakeElement()); },
    children: {},
  };
  return el;
}

// Loads app.js on a readable list (empty unless given) and returns the add form plus every list the app tried to save.
function loadApp(initial = []) {
  const elements = {};
  const saved = [];
  const replaced = [];
  let saveResult = 'saved';
  const store = {
    readError: false,
    load() { return { todos: initial, readError: false }; },
    save(todos) { saved.push(todos.map((t) => ({ ...t }))); return saveResult; },
    replace(todos) { replaced.push(todos); return 'saved'; },
  };
  const created = [];
  const document = {
    querySelector(sel) { return (elements[sel] ||= fakeElement()); },
    querySelectorAll() { return []; },
    createElement() { const el = fakeElement(); created.push(el); return el; },
  };
  // Fake timers: nothing runs until the test calls runTimers().
  const timers = [];
  const setTimeout = (fn, ms) => timers.push({ fn, ms, cleared: false, ran: false });
  const clearTimeout = (id) => { if (timers[id - 1]) timers[id - 1].cleared = true; };
  const runTimers = () => timers.filter((t) => !t.cleared && !t.ran).forEach((t) => { t.ran = true; t.fn(); });
  // Top-level functions of app.js (offerUndo, ...) end up on ctx.
  const ctx = { ...backup, ...due, store, document, crypto, setTimeout, clearTimeout };
  vm.runInNewContext(appJs, ctx);
  const submit = (value) => {
    document.querySelector('#title').value = value;
    document.querySelector('#add').onsubmit({ preventDefault() {} });
  };
  // The confirm dialog records each question and answers "Huỷ".
  const asked = [];
  Object.assign(document.querySelector('#confirm'), {
    showModal() { asked.push(document.querySelector('#confirm-text').textContent); },
    addEventListener(type, fn) { queueMicrotask(fn); },
  });
  const pick = (file) => document.querySelector('#import').onchange({ target: { files: [file], value: '' } });
  const count = () => document.querySelector('#count').textContent;
  // Clicks a filter tab: 'all', 'open' or 'done'.
  const filterBy = (f) => document.querySelector('#filters').onclick({ target: { dataset: { filter: f } } });
  const emptyShown = () => !document.querySelector('#empty').hidden;
  // The last drawn row of a todo, by title.
  const row = (title) => created.findLast((el) => el.children.span?.textContent === title);
  const undo = {
    shown: () => !document.querySelector('#undo').hidden,
    click: () => document.querySelector('#undo').onclick(),
  };
  const message = () => document.querySelector('#message').textContent;
  const failSaves = (result = 'failed') => { saveResult = result; };
  return { submit, saved, replaced, asked, pick, count, filterBy, emptyShown, ctx, timers, runTimers, row, undo, message, failSaves };
}

// A file whose text() resolves only when the test says so.
function slowFile(text) {
  let finish;
  const done = new Promise((resolve) => { finish = resolve; });
  return { file: { size: text.length, text: () => done.then(() => text) }, finish };
}

function backupOf(...titles) {
  return backup.toBackupText(titles.map((title, i) => ({ id: `id-${title}-${i}`, title, done: false, createdAt: 1 })));
}

test('add form: trims the title and makes a string id', () => {
  const { submit, saved } = loadApp();
  submit('  Mua sữa  ');
  assert.equal(saved.length, 1);
  const [t] = saved[0];
  assert.equal(t.title, 'Mua sữa');
  assert.equal(typeof t.id, 'string');
  assert.notEqual(t.id, '');
  assert.equal(t.done, false);
  assert.equal(typeof t.createdAt, 'number');
});

test('add form: skips a whitespace-only title', () => {
  const { submit, saved } = loadApp();
  submit('   ');
  submit('\t\n');
  assert.equal(saved.length, 0);
});

test('open-todo count line: a dot every three digits from 1,000 up, like every other sentence (Linh, R9)', () => {
  const todos = (n, done = false) =>
    Array.from({ length: n }, (_, i) => ({ id: `id-${done}-${i}`, title: `Việc ${i}`, done, createdAt: 1 }));
  const { submit, count } = loadApp([...todos(999), ...todos(5, true)]);
  assert.equal(count(), '999 việc chưa xong');
  submit('Việc thứ 1000');
  assert.equal(count(), '1.000 việc chưa xong');
  assert.equal(loadApp(todos(12)).count(), '12 việc chưa xong');
  assert.equal(loadApp(todos(2001)).count(), '2.001 việc chưa xong');
  assert.equal(loadApp(todos(12500)).count(), '12.500 việc chưa xong');
});

test('open-todo count line counts the whole list, whatever the filter (T-013)', () => {
  const todo = (i, done) => ({ id: `id-${i}`, title: `Việc ${i}`, done, createdAt: 1 });
  const { count, filterBy } = loadApp([todo(1, false), todo(2, false), todo(3, false), todo(4, true), todo(5, true)]);
  assert.equal(count(), '3 việc chưa xong');
  filterBy('done');
  assert.equal(count(), '3 việc chưa xong', 'tab "Đã xong"');
  filterBy('open');
  assert.equal(count(), '3 việc chưa xong', 'tab "Chưa xong"');
  filterBy('all');
  assert.equal(count(), '3 việc chưa xong', 'back to tab "Tất cả"');
});

test('count line says "Đã xong hết" when every todo is done, but not on an empty list (Thảo, PR 3)', () => {
  const todo = (i, done) => ({ id: `id-${i}`, title: `Việc ${i}`, done, createdAt: 1 });
  const { count, filterBy } = loadApp([todo(1, true), todo(2, true)]);
  assert.equal(count(), 'Đã xong hết');
  filterBy('open');
  assert.equal(count(), 'Đã xong hết', 'tab "Chưa xong"');
  assert.equal(loadApp([todo(1, false), todo(2, true)]).count(), '1 việc chưa xong');
  assert.equal(loadApp([]).count(), '0 việc chưa xong', 'an empty list keeps the count');
});

test('empty-list message only when the whole list is empty, not when a filter hides everything (T-014)', () => {
  const todo = (i, done) => ({ id: `id-${i}`, title: `Việc ${i}`, done, createdAt: 1 });
  const { emptyShown, filterBy } = loadApp([todo(1, false), todo(2, false), todo(3, false), todo(4, false)]);
  assert.equal(emptyShown(), false);
  filterBy('done');
  assert.equal(emptyShown(), false, 'tab "Đã xong" with no done todos');
  const allDone = loadApp([todo(1, true)]);
  allDone.filterBy('open');
  assert.equal(allDone.emptyShown(), false, 'tab "Chưa xong" with no open todos');
  assert.equal(loadApp([]).emptyShown(), true, 'a really empty list still shows it');
});

test('a backup of todos the app made imports again', () => {
  const { submit, saved } = loadApp();
  for (const v of ['Mua sữa', '  Gọi mẹ ', '   ', 'Nộp thuế']) submit(v);
  const todos = saved.at(-1);
  assert.equal(todos.length, 3);
  const parsed = backup.parseBackup(backup.toBackupText(todos));
  assert.equal(parsed.ok, true, parsed.message);
  assert.deepEqual(parsed.todos, todos);
});

test('two overlapping imports: the later-finishing one asks before replacing the list the first one filled', async () => {
  const { replaced, asked, pick } = loadApp();
  const large = slowFile(backupOf('Lớn 1', 'Lớn 2', 'Lớn 3'));
  const small = slowFile(backupOf('Nhỏ'));
  const first = pick(large.file);
  const second = pick(small.file);
  small.finish();
  await second;
  assert.equal(replaced.length, 1, 'the small file fills the empty list without asking');
  assert.deepEqual(asked, []);
  large.finish();
  await first;
  assert.deepEqual(asked, [backup.fill(backup.MESSAGES.confirmReplace, { n: 1, m: 3 })]);
  assert.equal(replaced.length, 1, 'cancelled, so the list from the small file stays');
});

// Shared Undo (plan han-chot-cho-viec, Q5, Q7; PR A step 4–5a). Nothing in the app offers an Undo yet, so these tests call
// offerUndo directly. restore() mutates the list given to loadApp, which is the app's own `todos` array until a remove.
const todo = (title, done = false) => ({ id: `id-${title}`, title, done, createdAt: 1 });
const D5 = due.DUE_TEXT.cleared.replace('{title}', 'A');

test('Undo: offerUndo shows the message and the button; "Hoàn tác" restores, saves, redraws, says D9, hides the button', () => {
  const list = [todo('A')];
  const app = loadApp(list);
  let restored = 0;
  app.ctx.offerUndo(D5, () => { restored++; list.push(todo('B')); });
  assert.equal(app.message(), D5);
  assert.equal(app.undo.shown(), true);
  assert.equal(app.saved.length, 0, 'offering an Undo saves nothing by itself');
  app.undo.click();
  assert.equal(restored, 1);
  assert.deepEqual(app.saved.at(-1).map((t) => t.title), ['A', 'B'], 'the restored list is saved');
  assert.equal(app.count(), '2 việc chưa xong', 'and redrawn');
  assert.equal(app.message(), due.DUE_TEXT.undone);
  assert.equal(app.undo.shown(), false);
  app.undo.click();
  assert.equal(restored, 1, 'a second click does nothing');
  assert.equal(app.saved.length, 1);
});

test('Undo: the button goes after 10 seconds, and the message stays (A16)', () => {
  const app = loadApp([todo('A')]);
  let restored = 0;
  app.ctx.offerUndo(D5, () => restored++);
  assert.equal(app.timers.at(-1).ms, 10000);
  app.runTimers();
  assert.equal(app.undo.shown(), false);
  assert.equal(app.message(), D5);
  app.undo.click();
  assert.equal(restored, 0);
  assert.equal(app.saved.length, 0);
});

test('Undo: adding, toggling, removing or importing hides the button; filtering does not (A16)', async () => {
  const cases = {
    add: (app) => app.submit('C'),
    toggle: (app) => app.row('A').children.input.onchange(),
    remove: (app) => app.row('A').children.button.onclick(),
    import: (app) => app.pick({ size: 0, text: async () => '' }),
  };
  for (const [name, act] of Object.entries(cases)) {
    const app = loadApp([todo('A'), todo('B')]);
    let restored = 0;
    app.ctx.offerUndo(D5, () => restored++);
    await act(app);
    assert.equal(app.undo.shown(), false, name);
    app.undo.click();
    assert.equal(restored, 0, `${name}: a hidden Undo does nothing`);
  }
  const app = loadApp([todo('A'), todo('B', true)]);
  let restored = 0;
  app.ctx.offerUndo(D5, () => restored++);
  app.filterBy('open');
  app.filterBy('all');
  assert.equal(app.undo.shown(), true, 'filtering keeps it');
  assert.equal(app.message(), D5);
  app.undo.click();
  assert.equal(restored, 1);
});

test('Undo: a new offer replaces the old one and stops its timer', () => {
  const app = loadApp([todo('A')]);
  const calls = [];
  app.ctx.offerUndo(D5, () => calls.push('first'));
  app.ctx.offerUndo('Hai', () => calls.push('second'));
  assert.equal(app.timers[0].cleared, true);
  assert.equal(app.message(), 'Hai');
  app.undo.click();
  assert.deepEqual(calls, ['second']);
});

test('Undo: when saving fails the message is D7, never D9; an unreadable saved list still says D9 (U1, Q4, Q5)', () => {
  const failed = loadApp([todo('A')]);
  failed.failSaves('failed');
  failed.ctx.offerUndo(D5, () => {});
  failed.undo.click();
  assert.equal(failed.message(), backup.MESSAGES.notSaved);
  assert.equal(failed.undo.shown(), false);
  const skipped = loadApp([todo('A')]);
  skipped.failSaves('skipped');
  skipped.ctx.offerUndo(D5, () => {});
  skipped.undo.click();
  assert.equal(skipped.message(), due.DUE_TEXT.undone, 'the read-error banner already explains a skipped save');
});
// Static checks on app/ files (plan/2026-10-19-khach-khong-mat-viec.md, commit B). Run: node --test
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const read = (f) => fs.readFileSync(path.join(__dirname, '..', 'app', f), 'utf8');
const html = read('index.html');

// Was store, backup, app; due.js comes before backup.js and app.js, which use it (plan han-chot-cho-viec, Q2).
test('scripts load in the order store, due, backup, app (Q2)', () => {
  const scripts = [...html.matchAll(/<script\b[^>]*\bsrc="([^"]+)"/g)].map((m) => m[1]);
  assert.deepEqual(scripts, ['store.js', 'due.js', 'backup.js', 'app.js']);
});

test('the Undo button sits hidden in the live notices area, with the text of D6 (plan han-chot-cho-viec, Q5, Q7)', () => {
  const { DUE_TEXT } = require('../app/due.js');
  assert.match(html, /<div id="notices" role="status" aria-live="polite">[\s\S]*<button type="button" id="undo" hidden>([^<]*)<\/button>\s*<\/div>/);
  assert.equal(html.match(/id="undo" hidden>([^<]*)</)[1], DUE_TEXT.undo);
});

test('no UTC day: app.js and due.js never call toISOString (A9)', () => {
  // A call, not the word: due.js names it in a comment to say it is not used.
  for (const f of ['app.js', 'due.js']) assert.doesNotMatch(read(f), /\.toISOString\s*\(/, f);
});

test('index.html loads nothing from outside (AC26, S4)', () => {
  assert.doesNotMatch(html, /\b(src|href)\s*=\s*["']?\s*(https?:)?\/\//i);
});

test('only store.js touches browser storage', () => {
  for (const f of ['app.js', 'backup.js', 'due.js']) assert.doesNotMatch(read(f), /localStorage/, f);
});

test('the main screen says where the list is kept, and has the new controls (AC23, U5)', () => {
  assert.ok(html.includes(
    'Danh sách chỉ được lưu trên trình duyệt này, nên xoá dữ liệu trang web, đổi trình duyệt hoặc đổi máy là mất, trừ khi bạn đã sao lưu ra file.'));
  assert.ok(html.includes('>Sao lưu ra file</button>'));
  assert.match(html, /<label[^>]*>Nhập từ file<input type="file"/);
  assert.match(html, /role="status"/);
  assert.match(html, /<dialog id="confirm" aria-labelledby="confirm-text">/);
});

test('confirm dialog buttons show a focus ring on any focus, not only :focus-visible (U5, PR 1)', () => {
  // Firefox gives the autofocused "Huỷ" no ring after the file picker closes: its :focus-visible heuristic
  // does not count that focus as keyboard focus. A rule on plain :focus does not depend on that heuristic.
  const css = read('style.css');
  assert.match(css, /dialog button:focus\s*\{[^}]*outline:\s*2px solid/);
});

test('visible text in index.html has no technical words (AC24, U4)', () => {
  const text = html.replace(/<script[\s\S]*?<\/script>/g, '').replace(/<[^>]+>/g, ' ');
  assert.doesNotMatch(text, /localStorage|JSON|console/i);
});

