tool_use_result.originalFile:
// Pins what add() in app/app.js makes, so a backup the app itself made always imports again (Khoa's review of commit B:
// isValidTodo rejects whitespace-only titles and non-string ids). app.js is a plain page script with no exports, so it
// runs unchanged in a vm context with a minimal fake page. Run: node --test
process.env.TZ = 'Asia/Ho_Chi_Minh'; // before any Date is made: "today" is the machine's day (A9)
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const crypto = require('node:crypto');
const backup = require('../app/backup.js');
const due = require('../app/due.js');

const appJs = fs.readFileSync(path.join(__dirname, '..', 'app', 'app.js'), 'utf8');

let focused = null; // document.activeElement of the fake page
function fakeElement() {
  const el = {
    textContent: '', innerHTML: '', hidden: false, value: '', className: '', dataset: {}, attributes: {},
    append() {},
    querySelector(sel) { return (el.children[sel] ||= fakeElement()); },
    setAttribute(name, value) { el.attributes[name] = String(value); },
    focus() { focused = el; el.onfocus?.(); },
    children: {},
  };
  return el;
}

// The page clock: 10/11/2026 06:00 in Asia/Ho_Chi_Minh, which is still 09/11 in UTC (A9).
const NOW = Date.UTC(2026, 10, 9, 23, 0);
class FixedDate extends Date {
  constructor(...a) { super(...(a.length ? a : [NOW])); }
  static now() { return NOW; }
}

// Loads app.js on a readable list (empty unless given) and returns the add form plus every list the app tried to save.
function loadApp(initial = []) {
  const elements = {};
  const saved = [];
  const replaced = [];
  let saveResult = 'saved';
  const store = {
    readError: false,
    load() { return { todos: initial, readError: false }; },
    save(todos) { saved.push(todos.map((t) => ({ ...t }))); return saveResult; },
    replace(todos) { replaced.push(todos); return 'saved'; },
  };
  const created = [];
  focused = null;
  const document = {
    querySelector(sel) { return (elements[sel] ||= fakeElement()); },
    querySelectorAll() { return []; },
    createElement() { const el = fakeElement(); created.push(el); return el; },
    get activeElement() { return focused; },
  };
  // #list keeps the rows of the last render(), in screen order.
  const list = document.querySelector('#list');
  list.rows = [];
  list.append = (li) => list.rows.push(li);
  Object.defineProperty(list, 'innerHTML', { set() { list.rows = []; }, get() { return ''; } });
  // Fake timers: nothing runs until the test calls runTimers().
  const timers = [];
  const setTimeout = (fn, ms) => timers.push({ fn, ms, cleared: false, ran: false });
  const clearTimeout = (id) => { if (timers[id - 1]) timers[id - 1].cleared = true; };
  const runTimers = () => timers.filter((t) => !t.cleared && !t.ran).forEach((t) => { t.ran = true; t.fn(); });
  // Top-level functions of app.js (offerUndo, ...) end up on ctx.
  const ctx = { ...backup, ...due, store, document, crypto, setTimeout, clearTimeout, Date: FixedDate };
  vm.runInNewContext(appJs, ctx);
  const submit = (value, date = '') => {
    document.querySelector('#title').value = value;
    document.querySelector('#due').value = date;
    document.querySelector('#add').onsubmit({ preventDefault() {} });
  };
  // The confirm dialog records each question and answers "Huỷ".
  const asked = [];
  Object.assign(document.querySelector('#confirm'), {
    showModal() { asked.push(document.querySelector('#confirm-text').textContent); },
    addEventListener(type, fn) { queueMicrotask(fn); },
  });
  const pick = (file) => document.querySelector('#import').onchange({ target: { files: [file], value: '' } });
  const count = () => document.querySelector('#count').textContent;
  // Clicks a filter tab: 'all', 'open' or 'done'.
  const filterBy = (f) => document.querySelector('#filters').onclick({ target: { dataset: { filter: f } } });
  const emptyShown = () => !document.querySelector('#empty').hidden;
  // The last drawn row of a todo, by title.
  const row = (title) => created.findLast((el) => el.children.span?.textContent === title);
  const undo = {
    shown: () => !document.querySelector('#undo').hidden,
    click: () => document.querySelector('#undo').onclick(),
  };
  const message = () => document.querySelector('#message').textContent;
  const failSaves = (result = 'failed') => { saveResult = result; };
  const shown = () => list.rows.map((li) => li.children.span.textContent);
  const sortBy = (value) => document.querySelector('#sort').onchange({ target: { value } });
  // The date field of a todo's row, as drawn now. blur(next): focus moves to `next` (null: nowhere).
  const dateField = (title) => {
    const el = row(title).children['input[type="date"]'];
    return {
      el,
      focus() { el.focus(); },
      change(value) { el.value = value; el.onchange(); },
      blur(next = null) { focused = next; el.onblur({ relatedTarget: next }); },
    };
  };
  return { submit, saved, replaced, asked, pick, count, filterBy, emptyShown, ctx, timers, runTimers, row, undo, message,
    failSaves, shown, sortBy, dateField, document };
}

// A file whose text() resolves only when the test says so.
function slowFile(text) {
  let finish;
  const done = new Promise((resolve) => { finish = resolve; });
  return { file: { size: text.length, text: () => done.then(() => text) }, finish };
}

function backupOf(...titles) {
  return backup.toBackupText(titles.map((title, i) => ({ id: `id-${title}-${i}`, title, done: false, createdAt: 1 })));
}

