  field.change('2026-11-15');
  assert.equal(last(app, 'B').dueDate, '2026-11-15');
  field.blur();
  assert.equal(app.saved.length, 1);
  assert.equal(app.message(), '');
  assert.equal(app.undo.shown(), false);
});

test('a due date cleared after a change in the same focus: Undo gives back the day saved last (Q3, A16)', () => {
  const app = loadApp([dated('B', '2026-11-12')]);
  const field = app.dateField('B');
