li .when { display: flex; align-items: center; gap: .4rem; font-size: .875rem; color: #555; }
li .when span:empty { display: none; }
/* #a3261b: about 6.8:1 on the page background, 7.3:1 under white text (U5, AA is 4.5:1). "Quá hạn" is written out too,
   so colour is not the only sign. */
li.overdue .due { color: #a3261b; font-weight: 600; }
.overdue-tag { background: #a3261b; color: #fff; border-radius: 3px; padding: 0 .35rem; font-weight: 600; }
