114	// focusTo: the element that has or is about to get focus. When it is a control of a row, the same control of the same todo
115	// gets focus in the new list, so a keyboard user is not sent back to the top of the page (AC9, U5).
116	function render(focusTo = document.activeElement) {
117	  const keep = focusTo && focusTo.dataset && focusTo.dataset.part ? { id: focusTo.dataset.id, part: focusTo.dataset.part } : null;
118	  let refocus = null;
119	  dirty = false;
120	  const list = $('#list');
121	  list.innerHTML = '';
122	  for (const t of visible()) {
123	    const li = document.createElement('li');
124	    // No user text in this template (S3): titles go in with textContent, the date label with setAttribute.
125	    li.innerHTML = `<label><input type="checkbox" ${t.done ? 'checked' : ''}> <span></span></label>` +
126	      '<span class="when"><span class="due"></span><span class="overdue-tag"></span><input type="date"></span>' +
127	      '<button aria-label="Xoá">×</button>';
128	    li.querySelector('span').textContent = t.title;
129	    const date = li.querySelector('input[type="date"]');
130	    date.value = isValidDueDate(t.dueDate) ? t.dueDate : '';
131	    date.setAttribute('aria-label', DUE_TEXT.rowLabel.replace('{title}', () => t.title));
132	    date.onfocus = () => { date.dataset.before = date.value; };
133	    date.onchange = () => { if (setDue(t.id, date.value)) drawDue(li, t); };
134	    date.onblur = (e) => {
135	      if (date.value === '') clearDue(t.id, date.dataset.before);
136	      if (dirty) render(e.relatedTarget); // the element focus moves to, since activeElement is still this field or body
137	    };
138	    li.querySelector('input').onchange = () => toggle(t.id);
139	    li.querySelector('button').onclick = () => remove(t.id);
140	    const parts = { toggle: li.querySelector('input'), due: date, remove: li.querySelector('button') };
141	    for (const [part, el] of Object.entries(parts)) Object.assign(el.dataset, { id: t.id, part });
142	    if (keep && keep.id === t.id) refocus = parts[keep.part];
143	    drawDue(li, t);
144	    list.append(li);
145	  }
146	  if (refocus) refocus.focus();
147	  const open = todos.filter((t) => !t.done).length;
148	  // Every todo done (and the list not empty): say so instead of "0 việc chưa xong" (Thảo, PR 3).
149	  $('#count').textContent = open === 0 && todos.length > 0 ? 'Đã xong hết' : `${formatCount(open)} việc chưa xong`;
150	  $('#unreadable').hidden = !store.readError;
151	  // Based on the whole list, not the filter; and not shown on a read error, where the list only looks empty.
152	  $('#empty').hidden = todos.length > 0 || store.readError;
153	}
