185	  render();
186	};
187	
188	$('#undo').onclick = undoLast;
189	
190	$('#export').onclick = () => {
191	  if (todos.length === 0) return show(MESSAGES.nothingToBackUp);
192	  const text = toBackupText(todos);
193	  const url = URL.createObjectURL(new Blob([text], { type: 'application/json' }));
194	  const a = document.createElement('a');
195	  a.href = url;
196	  a.download = backupFileName(new Date());
197	  document.body.append(a);
198	  a.click();
199	  a.remove();
200	  // Revoking right after click() can break the download on Safari iOS, so wait.
201	  setTimeout(() => URL.revokeObjectURL(url), 10000);
202	  show(tooBigToImport(text) ? MESSAGES.backupTooBig : fill(MESSAGES.backedUp, { n: todos.length }));
203	};
