1	// Due dates (plan/2026-10-19-han-chot-cho-viec.md, Q2). No DOM and no browser storage here, so this file can be tested in Node.
2	// A due date is a string YYYY-MM-DD on the todo (key `dueDate`, absent when there is none). "Today" is the machine's own day
3	// (local time), never the UTC day: no toISOString and no Date built from a due date string except through Date.UTC below.
4	
5	// Every new sentence and label of the due date feature (plan, Câu chữ). {title} is filled by the caller, {date} by formatDueDate.
6	const DUE_TEXT = {
7	  addLabel: 'Hạn chót', // D1
8	  rowLabel: 'Hạn chót của việc {title}', // D2
9	  dueOn: 'Hạn {date}', // D3
10	  overdue: 'Quá hạn', // D4
11	  cleared: 'Đã bỏ hạn chót của việc {title}.', // D5
12	  undo: 'Hoàn tác', // D6
13	  sortLabel: 'Xếp theo', // D8
14	  sortAdded: 'Thứ tự thêm', // D8
15	  sortDue: 'Hạn chót', // D8
16	  undone: 'Đã hoàn tác.', // D9
17	};
18	
19	// A string in the fixed form YYYY-MM-DD that is a real day (no 2026-02-30). Date.UTC + getUTC* so the time zone plays no part.
20	function isValidDueDate(v) {
21	  if (typeof v !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(v)) return false;
22	  const [y, m, d] = v.split('-').map(Number);
23	  const date = new Date(Date.UTC(y, m - 1, d));
24	  return date.getUTCFullYear() === y && date.getUTCMonth() === m - 1 && date.getUTCDate() === d;
25	}
26	
27	// The machine's own day as YYYY-MM-DD (A9).
28	function localDateString(date) {
29	  const pad = (n) => String(n).padStart(2, '0');
30	  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
31	}
32	
33	// today is localDateString(new Date()). Comparing strings works because the form is fixed (4-2-2 digits).
34	// Due today is not overdue (A6); a done todo never is (A7); a broken value counts as no due date (A14).
35	function isOverdue(todo, today) {
36	  return !todo.done && isValidDueDate(todo.dueDate) && todo.dueDate < today;
37	}
38	
39	// "Hạn DD/MM/YYYY" (A5). Only call it with a valid due date.
40	function formatDueDate(s) {
41	  const [y, m, d] = s.split('-');
42	  return DUE_TEXT.dueOn.replace('{date}', `${d}/${m}/${y}`);
43	}
44	
45	// A new array (the saved list keeps its added order, Q6): valid dates earliest first, then todos with no due date or a broken
46	// one. Ties keep the original order, by index, without relying on sort stability (A12).
47	function sortByDue(todos) {
48	  const key = (t) => (isValidDueDate(t.dueDate) ? t.dueDate : null);
49	  return todos
50	    .map((t, i) => ({ t, i, k: key(t) }))
51	    .sort((a, b) => {
52	      if (a.k !== b.k) {
53	        if (a.k === null) return 1;
54	        if (b.k === null) return -1;
55	        return a.k < b.k ? -1 : 1;
56	      }
57	      return a.i - b.i;
58	    })
59	    .map((x) => x.t);
60	}
61	
62	if (typeof module !== 'undefined') {
63	  module.exports = { DUE_TEXT, isValidDueDate, localDateString, isOverdue, formatDueDate, sortByDue };
64	}
